const incoming = $input.first().json;
let body = incoming.body ?? incoming;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = {};
  }
}

const message = typeof body.message === 'string' ? body.message.trim() : '';
const maxLength = 500;

if (!message) {
  return [{ json: {
    answer: 'Escribí una consulta para que pueda ayudarte.',
    sources: [],
    status: 'invalid_input'
  } }];
}

if (message.length > maxLength) {
  return [{ json: {
    answer: 'La consulta supera el límite de 500 caracteres. Acortala e intentá de nuevo.',
    sources: [],
    status: 'invalid_input'
  } }];
}

const normalize = (value) => value.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const query = normalize(message);

const knowledge = [
  {
    terms: ['carrera', 'carreras', 'analisis de sistemas', 'estudiar'],
    answer: 'El sitio del ISETA incluye una sección de carreras y una página dedicada a la Tecnicatura Superior en Análisis de Sistemas. Para confirmar la oferta académica vigente y sus condiciones, consultá la página institucional.',
    sources: [{ title: 'Tec. Sup. en Análisis de Sistemas', url: 'https://iseta.edu.ar/iseta/carreras/tec-sup-en-analisis-de-sistemas/' }]
  },
  {
    terms: ['horario', 'horarios', 'cronograma'],
    answer: 'El sitio dispone de una sección de Horarios. Revisá esa página para consultar la información publicada; este prototipo no puede confirmar si el cronograma tuvo cambios recientes.',
    sources: [{ title: 'Horarios', url: 'https://iseta.edu.ar/iseta/horarios/' }]
  },
  {
    terms: ['que es iseta', 'instituto', 'quienes son', 'sobre iseta'],
    answer: 'ISETA significa Instituto Experimental de Tecnología Alimentaria. La sección institucional del sitio presenta información sobre el instituto y su identidad.',
    sources: [{ title: '¿Quiénes somos?', url: 'https://iseta.edu.ar/iseta/institucionales/quienes-somos/' }]
  }
];

const match = knowledge.find(entry => entry.terms.some(term => query.includes(normalize(term))));
if (match) {
  return [{ json: { answer: match.answer, sources: match.sources, status: 'ok' } }];
}

return [{ json: {
  answer: 'No tengo información verificada suficiente para responder esa consulta en esta versión de prueba. Probá con una pregunta sobre carreras, horarios o información institucional, o consultá directamente el sitio del ISETA.',
  sources: [{ title: 'Sitio institucional del ISETA', url: 'https://iseta.edu.ar/iseta/' }],
  status: 'insufficient_context'
} }];
